// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        // Assumptions to avoid reverts and edge cases
        vm.assume(sender != address(0));
        vm.assume(target != address(0));

        // We need to have the flash governance asset set; we'll use a dummy token
        // For simplicity, assume the asset is not set and we just call the function

        // Try calling assertGovernanceApproved, catch reverts
        bool reverted;
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));
        reverted = !success;

        // The general rule: after the call, DAO is either the initial value (address(this)) 
        // or it remains unchanged from whatever it was before (which was address(this) initially,
        // but if setDAO had been called it could change). Since we never call setDAO,
        // DAO should always equal address(this) in the correct implementation.
        // In the buggy version, setDAO doesn't set DAO, so DAO remains address(0), which is the default.
        // So we assert that DAO equals address(this) (the initial value) unless the call reverted.
        // If reverted, we assert that DAO remains unchanged (still equals address(this)).
        address daoAfter = address(c.DAO());
        if (reverted) {
            assertTrue(daoAfter == address(this), "After revert, DAO should be unchanged");
        } else {
            // After successful call, DAO should still be address(this) because setDAO was never called
            assertTrue(daoAfter == address(this), "After success, DAO should be address(this)");
        }

        // Alternative: a more general rule that holds for both implementations:
        // The DAO address is either address(this) (initial) or address(0) (if setDAO was never called and bug exists)
        // But the buggy version never sets DAO, so it remains address(0) always.
        // So a rule that the reference satisfies but the buggy version breaks is:
        // After calling assertGovernanceApproved, DAO is always address(this).
    }
}

